/* Généré par tools/ck_build.py depuis data/ck/ : ne pas modifier à la main. */
window.CK_HYP={"acidocetose-diabetique":{"bloquant":true,"confirmation":"L’acidocétose diabétique se confirme quand trois critères sont présents : une glycémie supérieure à 11 millimoles par litre ou un diabète connu, des corps cétoniques supérieurs à 3 millimoles par litre ou une cétonurie d’au moins deux croix, et un bicarbonate inférieur à 15 millimoles par litre ou un pH veineux inférieur à 7,3.","exam":{"lignes":[{"mecanisme":"Le manque d’insuline empêche les cellules d’utiliser le glucose et libère les acides gras, que le foie transforme en corps cétoniques acides.","nom":"Glycémie et corps cétoniques au lit (sang capillaire)","pourquoi_ce_choix":"La mesure au lit donne le diagnostic en quelques minutes et suit l’effet du traitement heure par heure.","principe":"Le lecteur capillaire mesure au lit la glycémie et la concentration de bêta-hydroxybutyrate dans le sang.","rang":1,"recherche":"Il recherche une glycémie supérieure à 11 millimoles par litre, ou un diabète connu, et des corps cétoniques supérieurs à 3 millimoles par litre.","src":[{"id":"R-JBDS-DKA","loc":"Diagnosis of DKA ; Point of care testing","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les corps cétoniques consomment le bicarbonate du sang et provoquent une acidose métabolique.","nom":"Gaz du sang veineux : pH, bicarbonate et potassium","pourquoi_ce_choix":"Il confirme l’acidose, avec un bicarbonate inférieur à 15 millimoles par litre ou un pH veineux inférieur à 7,3, et il donne le potassium qui guide la perfusion.","principe":"Le gaz du sang veineux mesure le pH, le bicarbonate et le potassium sans ponction artérielle.","rang":2,"recherche":"Il recherche l’acidose métabolique et le niveau du potassium.","src":[{"id":"R-JBDS-DKA","loc":"Diagnosis of DKA ; Box 1 et Box 2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une infection, un infarctus ou un arrêt de l’insuline déclenchent souvent l’acidocétose.","nom":"Recherche de la cause : hémocultures, ECG, radiographie du thorax, analyse d’urine","pourquoi_ce_choix":"Le traitement de la cause fait partie de la prise en charge, et la ligne directrice les inclut dans le bilan initial.","principe":"Ces examens recherchent le facteur déclenchant à l’origine de la décompensation.","rang":3,"recherche":"Ils recherchent une infection, une ischémie du myocarde ou un autre facteur déclenchant.","src":[{"id":"R-JBDS-DKA","loc":"Box 1, Action 4 et Action 6","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"acidocetose-diabetique","label":"Acidocétose diabétique","pec":{"mesures_generales":["L’équipe de diabétologie participe à la prise en charge dès que possible.","La glycémie et les corps cétoniques se contrôlent chaque heure, et le gaz du sang veineux avec le potassium à 60 minutes, à 2 heures, puis toutes les 2 heures.","La cause déclenchante se recherche et se traite en même temps."],"moyens_specifiques":[{"dose_ref":null,"limites":"Le débit se réduit chez le sujet âgé, l’adolescent, en cas d’insuffisance cardiaque ou rénale, à cause du risque de surcharge ; l’œdème cérébral, rare chez l’adulte, menace surtout le jeune adulte.","mecanisme":"Le glucose qui passe dans l’urine entraîne une diurèse osmotique qui déshydrate le patient : un adulte de 70 kilos peut avoir perdu jusqu’à 7 litres.","pourquoi_ce_choix":"La ligne directrice considère le remplissage comme la première mesure thérapeutique, avant l’insuline.","principe":"On rétablit le volume circulant et la perfusion des reins par des cristalloïdes intraveineux, ce qui aide aussi à éliminer les corps cétoniques.","src":[{"id":"R-JBDS-DKA","loc":"General management issues, Fluid administration and deficits ; Cerebral oedema","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le sérum physiologique, ou un cristalloïde balancé, se perfuse en premier, plus vite en cas d’hypotension ; les volumes et les débits restent À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle expose à l’hypoglycémie et à l’hypokaliémie, ce qui impose une surveillance horaire ; l’acidocétose est résolue quand les corps cétoniques sont inférieurs à 0,6 millimole par litre et le pH veineux supérieur à 7,3.","mecanisme":"Sans insuline, le foie continue de fabriquer des corps cétoniques et du glucose.","pourquoi_ce_choix":"Le débit fixe vise la disparition des corps cétoniques, pas seulement la baisse de la glycémie ; la poursuite de l’insuline basale prépare l’arrêt de la perfusion.","principe":"On bloque la production de corps cétoniques par une perfusion intraveineuse continue d’insuline à débit fixe, calculé sur le poids.","src":[{"id":"R-JBDS-DKA","loc":"Insulin therapy ; Box 4, Resolution of DKA","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une perfusion intraveineuse d’insuline humaine rapide à débit fixe selon le poids commence après le début du remplissage ; l’insuline basale habituelle se poursuit, et du glucose s’ajoute quand la glycémie baisse. Le débit reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Il ne se donne qu’avec des contrôles répétés de la kaliémie ; une kaliémie anormale impose une surveillance de l’ECG.","mecanisme":"L’insuline fait entrer le potassium dans les cellules, alors que la diurèse osmotique a déjà vidé les réserves de l’organisme.","pourquoi_ce_choix":"Il prévient l’hypokaliémie provoquée par l’insuline, qui expose aux arythmies ; la ligne directrice vise une kaliémie entre 4,0 et 5,5 millimoles par litre.","principe":"On compense ces pertes en ajoutant du chlorure de potassium aux perfusions selon la kaliémie mesurée.","src":[{"id":"R-JBDS-DKA","loc":"Box 1, Potassium replacement ; Box 3 ; Hypokalaemia and hyperkalaemia","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le potassium s’ajoute à la perfusion selon la kaliémie, avec un avis senior si elle est inférieure à 3,5 millimoles par litre ; les quantités restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à restaurer la volémie, à arrêter la production de corps cétoniques et à corriger les troubles électrolytiques sans provoquer de complication."},"src":[{"id":"R-JBDS-DKA","loc":"Diagnosis ; Management","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-kussmaul"]},"anaphylaxie":{"bloquant":true,"confirmation":"Le diagnostic repose sur les critères cliniques ; une tryptase élevée le soutient a posteriori, et le bilan allergologique recherche ensuite le déclencheur.","exam":{"lignes":[{"mecanisme":"Un allergène, souvent par un mécanisme lié aux IgE, active brutalement les mastocytes et les basophiles, qui libèrent de l’histamine et d’autres médiateurs dans tout l’organisme.","nom":"Diagnostic clinique selon les critères de l’EAACI","pourquoi_ce_choix":"Le diagnostic est clinique et immédiat, car l’adrénaline ne doit attendre aucun résultat de laboratoire.","precautions":"Chez l’adulte, une pression systolique inférieure à 90 mmHg, ou une baisse de plus de 30 % par rapport à sa valeur habituelle, après exposition à un allergène connu suffit au diagnostic.","principe":"Les critères reconnaissent l’anaphylaxie devant une atteinte brutale de la peau ou des muqueuses avec une atteinte respiratoire ou une baisse de la pression, devant deux atteintes après exposition à un allergène probable, ou devant une hypotension après exposition à un allergène connu.","rang":1,"recherche":"Il recherche l’urticaire ou l’angio-œdème, la dyspnée, le stridor ou les sibilants, l’hypotension et des troubles digestifs persistants.","src":[{"id":"R-EAACI-ANA","loc":"Box 1, Clinical criteria for diagnosing anaphylaxis","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les mastocytes activés libèrent de la tryptase, qui reste élevée quelques heures dans le sang.","nom":"Dosage de la tryptase sérique, à distance du traitement","pourquoi_ce_choix":"Il ne guide pas le traitement immédiat mais soutient plus tard le diagnostic et le bilan allergologique ; une valeur supérieure à 1,2 fois la valeur de base plus 2 microgrammes par litre soutient le diagnostic.","precautions":"Une tryptase normale n’exclut pas l’anaphylaxie, surtout chez l’enfant et lors d’une allergie alimentaire.","principe":"Un dosage fait entre 30 minutes et 2 heures après le début, comparé à un dosage de base fait au moins 24 heures après la guérison, documente l’activation des mastocytes.","rang":2,"recherche":"Il recherche une élévation transitoire de la tryptase sérique.","src":[{"id":"R-EAACI-ANA","loc":"Diagnosis, recommandation sur la tryptase","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"anaphylaxie","label":"Anaphylaxie","pec":{"mesures_generales":["L’équipe demande de l’aide tôt et injecte l’adrénaline sans attendre.","Le patient reste surveillé 6 à 8 heures après une atteinte respiratoire, et au moins 12 à 24 heures après une hypotension, à cause du risque de réaction prolongée ou biphasique.","Avant sa sortie, le patient à risque de récidive reçoit un auto-injecteur d’adrénaline, une instruction écrite et un rendez-vous chez un allergologue."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle peut échouer en cas de détresse respiratoire réfractaire ou d’hypotension : l’adrénaline intraveineuse se réserve alors à une équipe formée en milieu surveillé. Un patient sous bêtabloquant peut mal y répondre.","mecanisme":"Les médiateurs des mastocytes dilatent les vaisseaux, rendent les capillaires perméables et contractent les bronches.","pourquoi_ce_choix":"La voie intramusculaire à la cuisse donne des taux plasmatiques plus élevés que la voie sous-cutanée, l’inhalation ou l’injection dans le deltoïde, avec peu d’effets graves, contrairement à la voie intraveineuse ; son emploi précoce semble réduire les réactions biphasiques.","principe":"L’adrénaline contre ces effets : elle resserre les vaisseaux, renforce la contraction du cœur et dilate les bronches.","src":[{"id":"R-EAACI-ANA","loc":"Management, First line intervention: adrenaline, Route of administration","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’adrénaline intramusculaire, injectée sans délai au milieu de la cuisse, est le traitement de première ligne, et elle se répète si la réponse manque. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le remplissage ne remplace jamais l’adrénaline, et ses volumes chez l’insuffisant cardiaque restent À vérifier.","mecanisme":"La fuite capillaire et la vasodilatation vident le compartiment vasculaire du patient en choc anaphylactique.","pourquoi_ce_choix":"L’adrénaline peut rester inefficace tant que le volume circulant n’est pas restauré, ce qui justifie un remplissage précoce.","principe":"On restaure le volume circulant par des bolus intraveineux de cristalloïdes.","src":[{"id":"R-EAACI-ANA","loc":"Management, intravenous fluids","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient avec atteinte cardiovasculaire reçoit des cristalloïdes intraveineux dès la première injection d’adrénaline, en bolus répétés selon la réponse ; les volumes restent À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"L’adrénaline inhalée passe très peu dans le sang et ne remplace jamais l’injection intramusculaire ; les glucocorticoïdes pourraient être délétères chez l’enfant.","mecanisme":"Le bronchospasme et l’œdème du larynx peuvent persister malgré l’adrénaline intramusculaire.","pourquoi_ce_choix":"Ces traitements agissent sur place là où l’obstruction persiste ; les antihistaminiques soulagent seulement les signes cutanés, et l’effet des glucocorticoïdes reste mal prouvé.","principe":"On ajoute un bronchodilatateur inhalé, ou de l’adrénaline nébulisée, qui agit au contact de la zone atteinte.","src":[{"id":"R-EAACI-ANA","loc":"Management, Inhaled Beta2-Agonists, Inhaled adrenaline, H1 and H2 antihistamines, Glucocorticoids","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le salbutamol inhalé s’ajoute si l’obstruction bronchique domine, et l’adrénaline nébulisée avec de l’oxygène si un œdème du larynx ou du pharynx est suspecté ; les antihistaminiques et les glucocorticoïdes ne viennent qu’en second. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à contrer immédiatement les effets des médiateurs sur les voies aériennes et la circulation, puis à prévenir une récidive."},"src":[{"id":"R-EAACI-ANA","loc":"Recommendations, Table 2 ; Management","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-reaction-allergique","urg-choc"]},"avc-hemorragique":{"bloquant":true,"confirmation":"Le diagnostic est posé par l’imagerie cérébrale, qui montre l’hématome dans le tissu cérébral.","exam":{"lignes":[{"mecanisme":"Une artère rompue saigne dans le cerveau, et l’hématome peut grossir dans les premières heures.","nom":"Scanner cérébral sans injection en urgence","pourquoi_ce_choix":"Il est rapide et distingue l’hémorragie de l’ischémie, ce qui décide de tout le traitement : une thrombolyse est exclue.","precautions":"L’équipe recherche d’emblée un traitement anticoagulant, car sa neutralisation est urgente.","principe":"Le scanner sans injection montre l’hématome, son siège, son volume et une extension dans les ventricules.","rang":1,"recherche":"Il montre l’hématome, son siège, son volume et une extension dans les ventricules.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1, Additional information","lu_le":"2026-10-17"},{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une angiographie normale au scanner n’exclut pas une malformation ; l’artériographie numérisée reste l’examen de référence.","mecanisme":"Chez le sujet jeune, un hématome lobaire ou cérébelleux sans hypertension connue peut venir d’une anomalie des vaisseaux.","nom":"Angioscanner, IRM ou angio-IRM","pourquoi_ce_choix":"Ces examens se font sans cathétérisme et en urgence, ce qui les place avant l’artériographie.","principe":"L’imagerie vasculaire montre une malformation artérioveineuse, un anévrisme, une fistule durale, une malformation caverneuse ou une thrombose veineuse.","rang":2,"recherche":"Elle recherche une cause macrovasculaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1 et 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une petite malformation vasculaire peut échapper à l’angioscanner.","nom":"Artériographie numérisée par cathétérisme","pourquoi_ce_choix":"C’est l’examen de référence des malformations ; on le garde pour une suspicion qui persiste malgré un angioscanner normal.","precautions":"Elle est invasive, avec environ 0,6 % de complications ; l’indication se décide au cas par cas.","principe":"Un cathéter injecte le produit de contraste directement dans les artères, ce qui donne une image plus fine.","rang":3,"recherche":"Elle recherche une malformation vasculaire que l’angioscanner n’a pas montrée.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-hemorragique","label":"Hémorragie intracérébrale spontanée","pec":{"mesures_generales":["Le patient est admis dans une unité de l’AVC organisée, sauf s’il relève des soins intensifs.","Un avis neurochirurgical est demandé tôt en cas d’hématome volumineux, d’hémorragie dans les ventricules ou d’hématome compressif de la fosse postérieure.","Un dépistage des troubles de la déglutition est fait, et aucune décision de non-réanimation n’est prise dans les 24 premières heures sauf volonté claire du patient."],"moyens_specifiques":[{"limites":"La baisse ne dépasse pas 70 mmHg et la pression ne descend pas sous 110 mmHg ; la recommandation ne porte pas sur les hématomes plus volumineux.","mecanisme":"Une pression artérielle élevée s’associe à l’expansion de l’hématome, au décès et à la dépendance.","pourquoi_ce_choix":"Cette mesure ne demande ni geste invasif ni centre spécialisé, et la ligne directrice la propose pour les hématomes de petit ou moyen volume.","principe":"Abaisser tôt la pression vise à prévenir l’expansion de l’hématome et l’aggravation clinique.","src":[{"id":"R-ESO-ICH","loc":"Blood pressure management ; PICO 2, Expert consensus statements","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La pression systolique est abaissée sous 140 mmHg dans les 6 heures pour un hématome de moins de 30 millilitres. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le niveau de preuve reste faible ou très faible pour les antidotes, et le risque d’événements thromboemboliques doit être pesé.","mecanisme":"Sous anticoagulant, la coagulation est diminuée, et l’hématome risque davantage de grossir.","pourquoi_ce_choix":"Le moyen dépend de la molécule : concentré de complexe prothrombinique avec vitamine K intraveineuse sous antivitamine K, idarucizumab sous dabigatran, andexanet alfa ou concentré de complexe prothrombinique sous inhibiteur du facteur Xa.","principe":"On rétablit la coagulation en neutralisant l’anticoagulant le plus vite possible.","src":[{"id":"R-ESO-ICH","loc":"PICO 3.3.1 à 3.3.2.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’anticoagulant est neutralisé en urgence par un moyen adapté à la molécule. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le bénéfice n’est pas uniforme, et la décision reste individuelle après un avis neurochirurgical.","mecanisme":"L’hématome comprime le cerveau, et ses produits de dégradation déclenchent une inflammation qui ajoute une lésion secondaire.","pourquoi_ce_choix":"Elle n’est proposée que si le siège, le volume, l’état neurologique, le délai et l’expérience de l’équipe la rendent favorable, car les essais donnent des résultats différents selon ces facteurs.","principe":"On retire l’hématome pour lever la compression et limiter la lésion secondaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 4.1 ; Surgery, Analysis of current evidence","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une évacuation chirurgicale d’un hématome supratentoriel peut être proposée.","type":"chirurgie"}],"objectif":"Le traitement vise à limiter l’expansion de l’hématome et les complications pour réduire le décès et la dépendance."},"src":[{"id":"R-ESO-ICH","loc":"Abstract ; PICO 1 à 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"avc-ischemique":{"bloquant":true,"confirmation":"Le diagnostic repose sur un déficit neurologique focal brutal avec une imagerie qui exclut une hémorragie ; l’IRM de diffusion montre l’infarctus.","exam":{"lignes":[{"alternative":"Lors d’un AVC constaté au réveil, une IRM qui montre un décalage diffusion-FLAIR permet encore la thrombolyse si une thrombectomie n’est pas prévue.","mecanisme":"Un caillot bouche une artère du cerveau ; autour du cœur de l’infarctus, une zone mal perfusée reste récupérable pendant quelques heures.","nom":"Imagerie cérébrale en urgence (scanner sans injection ou IRM)","pourquoi_ce_choix":"Le bénéfice de la reperfusion baisse avec le temps : l’examen le plus rapide qui exclut une hémorragie passe donc en premier. L’IRM convient aussi si elle ne retarde pas le traitement.","precautions":"Sous antivitamine K, la thrombolyse n’est faite que si l’INR est connu et ne dépasse pas 1,7 ; après un anticoagulant oral direct pris dans les 48 heures, elle exige un dosage spécifique.","principe":"Le scanner sans injection montre une hémorragie, qui interdit la thrombolyse, et l’étendue des signes précoces d’ischémie.","rang":1,"recherche":"Elle recherche une hémorragie et l’étendue des signes précoces d’ischémie.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h ; 4,5 à 9 h ; AVC grave (ASPECTS)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Quand le caillot bouche une grosse artère de la circulation antérieure, il menace un vaste territoire et peut être retiré mécaniquement.","nom":"Angioscanner ou angio-IRM des vaisseaux cervicaux et intracrâniens","pourquoi_ce_choix":"Elle seule désigne les patients qui gagnent à une thrombectomie : celle-ci améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si les critères des essais sont remplis.","precautions":"Les précautions du produit de contraste (fonction rénale, allergie) restent À vérifier dans une source suisse ou européenne.","principe":"L’injection opacifie les artères et montre l’endroit où le flux s’arrête.","rang":2,"recherche":"Elle recherche l’occlusion d’une grosse artère de la circulation antérieure.","src":[{"id":"R-ESO-MT","loc":"PICO 1 et 2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le délai seul ne dit pas si le tissu est perdu : chez certains patients, une zone récupérable persiste au-delà de 4,5 heures.","nom":"Imagerie de perfusion (scanner ou IRM)","pourquoi_ce_choix":"Elle ne sert qu’au-delà de 4,5 heures ou si l’heure de début est inconnue, car le scanner sans injection ne montre pas ce tissu récupérable ; dans les 4,5 heures, elle ne doit pas retarder la thrombolyse.","principe":"Elle compare le cœur de l’infarctus et la zone mal perfusée ; leur décalage quantifie le tissu encore récupérable.","rang":3,"recherche":"Elle mesure le cœur de l’infarctus et la zone mal perfusée encore récupérable.","src":[{"id":"R-ESO-IVT","loc":"Recommandations 4,5 à 9 h et AVC du réveil","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"PICO 2, critères DEFUSE-3 et DAWN","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-ischemique","label":"Accident vasculaire cérébral ischémique","pec":{"mesures_generales":["Le patient rejoint sans délai un centre de l’AVC, et l’équipe note l’heure de début ou celle où il a été vu sans déficit pour la dernière fois.","Une pression artérielle supérieure à 185/110 mmHg doit être abaissée avant la thrombolyse ; si elle reste plus haute, la thrombolyse n’est pas faite.","Aucun antithrombotique n’est donné dans les 24 heures qui suivent la thrombolyse."],"moyens_specifiques":[{"limites":"Elle augmente le risque d’hémorragie cérébrale symptomatique, d’environ 3 % avec l’altéplase : une hémorragie doit donc être exclue avant. Elle n’est pas faite si la pression reste au-dessus de 185/110 mmHg, si l’INR dépasse 1,7 sous antivitamine K, ou après un anticoagulant oral direct pris dans les 48 heures sans dosage spécifique.","mecanisme":"Le caillot prive de sang une zone qui meurt en quelques heures si le flux ne revient pas.","pourquoi_ce_choix":"Elle se donne par simple injection, sans attendre un centre de thrombectomie, et améliore le pronostic dans les 4,5 heures. La ténectéplase, plus spécifique de la fibrine et de durée d’action plus longue, se donne en une seule injection ; la ligne directrice la propose avant une thrombectomie.","principe":"On rétablit le flux en dissolvant le caillot : un médicament thrombolytique est injecté dans une veine.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h, > 80 ans, ténectéplase, pression artérielle, anticoagulants ; hémorragie symptomatique","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombolyse intraveineuse par altéplase ou ténectéplase se fait dans les 4,5 heures, y compris après 80 ans. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elle ne concerne que l’occlusion d’une grosse artère prouvée par l’imagerie et exige un centre spécialisé ; ses complications propres restent À vérifier dans une source européenne.","mecanisme":"Un caillot dans une grosse artère menace un vaste territoire cérébral.","pourquoi_ce_choix":"Elle vise une reperfusion complète de la grosse artère ; elle améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si l’imagerie montre encore du tissu récupérable selon les critères des essais. La ligne directrice admet les deux techniques de retrait.","principe":"On rétablit le flux en retirant le caillot par un cathéter, avec un stent retriever ou par aspiration au contact.","src":[{"id":"R-ESO-MT","loc":"PICO 1, 2 et 8 ; Organisation des soins (mothership, drip-and-ship)","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombectomie mécanique se fait dans un centre de l’AVC qui la pratique, en plus de la thrombolyse quand celle-ci est indiquée.","type":"interventionnel"}],"objectif":"Le traitement vise à rétablir le plus vite possible la perfusion du cerveau encore viable pour améliorer le pronostic fonctionnel."},"src":[{"id":"R-ESO-IVT","loc":"Résumé et recommandations","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"Résumé","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 Présentation typique","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"bell":{"bloquant":false,"confirmation":"Le diagnostic est retenu devant une paralysie faciale périphérique installée en 12 à 72 heures, sans autre cause trouvée à l’examen et aux examens ciblés.","exam":{"lignes":[{"mecanisme":"Une paralysie faciale périphérique a une autre cause que la paralysie de Bell dans 25 à 40 % des cas.","nom":"Examen neurologique complet et otoscopie","pourquoi_ce_choix":"Ce sont des gestes immédiats qui écartent les causes graves ou spécifiques avant de retenir un diagnostic d’exclusion.","precautions":"Une atteinte bilatérale, plusieurs nerfs crâniens atteints, un spasme facial ou une évolution chronique sont atypiques et font rechercher une autre cause.","principe":"L’examen neurologique cherche d’autres déficits, et l’otoscopie cherche une cause dans l’oreille.","rang":1,"recherche":"Ils recherchent un autre déficit neurologique et des vésicules du conduit auditif externe, une otite moyenne ou un cholestéatome.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; Die wichtigsten Empfehlungen ; § 2.2","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire ; chez l’adulte, la ligne directrice allemande la recommande, alors que le protocole des HUG la réserve aux présentations atypiques.","mecanisme":"Une neuroborréliose, un diabète ou une infection peuvent donner le même tableau.","nom":"Sérologie de Borrelia, glycémie et hémoglobine glyquée ; sérologies VIH et syphilis selon le protocole des HUG","pourquoi_ce_choix":"La ligne directrice exige au moins la sérologie de Borrelia, car la neuroborréliose se traite par antibiotique et non par corticoïde ; une sérologie du virus varicelle-zona s’ajoute en cas de suspicion de zona.","principe":"Le sang montre des anticorps contre Borrelia, une glycémie élevée ou les marqueurs d’une infection.","rang":2,"recherche":"Elles recherchent une neuroborréliose, un diabète et une cause infectieuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 4 Examens complémentaires","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une tumeur ou une lésion du rocher peut imiter une paralysie de Bell, et la perte axonale détermine la récupération.","nom":"IRM et électroneuromyographie (ENMG)","pourquoi_ce_choix":"L’IRM n’est indiquée qu’en cas de présentation atypique ; l’ENMG vers le 10e jour évalue le pronostic des formes sévères.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète.","principe":"L’IRM montre un processus le long du trajet du nerf ; l’ENMG mesure la réponse des muscles à la stimulation du nerf.","rang":3,"recherche":"L’IRM recherche un processus de l’angle ponto-cérébelleux, du rocher, de la parotide ou du tronc cérébral ; l’ENMG mesure la perte axonale.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 ; § 2.4 Bildgebung","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"bell","label":"Paralysie faciale idiopathique (paralysie de Bell)","pec":{"mesures_generales":["La sévérité est cotée selon House-Brackmann, et le patient est revu ; une forme sévère (grades IV à VI) est revue en neurologie vers le 10e jour.","Une grossesse ne change pas la conduite, mais la corticothérapie débute de préférence à l’hôpital avec un avis obstétrical."],"moyens_specifiques":[{"limites":"Le bénéfice n’est démontré que si le traitement débute dans les 72 heures ; des troubles du sommeil ont été rapportés, et les contre-indications restent À vérifier dans l’information professionnelle suisse.","mecanisme":"La cause reste discutée : la ligne directrice cite une inflammation auto-immune, une réactivation du virus herpès simplex de type 1 et des facteurs ischémiques.","pourquoi_ce_choix":"C’est le seul traitement dont les essais montrent qu’il favorise la récupération complète et réduit les syncinésies, avec un nombre de sujets à traiter de 10 ; un antiviral seul n’apporte pas ce bénéfice.","principe":"Le corticoïde agit contre la composante inflammatoire de l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 1 Einführung ; Die wichtigsten Empfehlungen ; Tabelle 3 et 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale débute dans les 72 heures. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Il ne remplace jamais le corticoïde ; la décision se prend au cas par cas après information du patient.","mecanisme":"Une réactivation du virus herpès simplex de type 1 fait partie des causes discutées.","pourquoi_ce_choix":"Il ne s’ajoute que dans les formes sévères, où il peut apporter un bénéfice supplémentaire : grades V et VI selon la ligne directrice allemande, grades IV à VI ou suspicion de zona selon le protocole des HUG.","principe":"Un antiviral freine la multiplication du virus en plus de l’effet du corticoïde.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un antiviral peut s’ajouter au corticoïde dans les formes sévères. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"},{"limites":"Le délai et le choix de la technique restent À vérifier dans une source suisse ou européenne.","mecanisme":"Quand le nerf ne récupère pas, la paralysie devient définitive.","pourquoi_ce_choix":"Ces gestes ne se discutent qu’après l’échec de la récupération spontanée, qui reste la règle dans la paralysie de Bell.","principe":"On aide la fermeture des paupières ou l’on apporte au visage une autre commande nerveuse ou un autre muscle.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.2 Nicht medikamentöse Therapie","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une charge palpébrale ou une réanimation microchirurgicale peut être proposée (anastomose du nerf hypoglosse sur le nerf facial, greffe transfaciale, transfert musculaire).","type":"chirurgie"}],"objectif":"Le traitement vise une récupération complète et la prévention des séquelles, syncinésies et lésion de la cornée."},"src":[{"id":"R-DGN-BELL","loc":"Die wichtigsten Empfehlungen ; § 1 ; § 2 ; § 3","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule","vii-site3-tympanique","vii-site4-mastoidien"]},"cholesteatome":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie, l’examen ORL et l’imagerie.","exam":{"lignes":[{"mecanisme":"Le cholestéatome grossit dans l’oreille moyenne et érode l’os jusqu’au canal facial ; la paralysie s’installe lentement.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple et immédiate, et un début lent de la paralysie doit la faire répéter avec soin.","principe":"L’otoscopie montre le cholestéatome dans l’oreille moyenne.","rang":1,"recherche":"Elle recherche le cholestéatome dans l’oreille moyenne.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’extension du cholestéatome et l’atteinte du canal facial décident de la chirurgie.","nom":"Examen ORL et imagerie du rocher","pourquoi_ce_choix":"La ligne directrice demande un examen ORL et une IRM devant un processus du rocher ; le choix précis de l’imagerie reste À vérifier.","principe":"L’examen ORL et l’imagerie précisent l’extension et l’état du canal facial.","rang":2,"recherche":"Ils précisent l’extension du cholestéatome et l’atteinte du canal facial.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.4 ; § 2.5","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"cholesteatome","label":"Cholestéatome","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source suisse ou européenne.","mecanisme":"Le cholestéatome comprime et érode le canal facial.","pourquoi_ce_choix":"Le choix et les modalités de l’intervention restent À vérifier dans une source suisse ou européenne.","principe":"On retire le cholestéatome pour libérer le nerf.","statut":"À vérifier","texte":"Le cholestéatome est retiré par une chirurgie de l’oreille moyenne.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à enlever le cholestéatome et à libérer le nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"dissection-aortique":{"bloquant":true,"confirmation":"La dissection se confirme quand l’imagerie montre un voile intimal séparant un vrai et un faux chenal ; elle est de type A si elle atteint l’aorte ascendante, de type B sinon.","exam":{"lignes":[{"mecanisme":"La déchirure de l’intima et le faux chenal qui en naît donnent des signes typiques : terrain à risque, douleur brutale et déchirante, déficit de pouls, souffle d’insuffisance aortique, déficit neurologique.","nom":"Algorithme ADD-RS : score clinique, échocardiographie ciblée et D-dimères","pourquoi_ce_choix":"La ligne directrice recommande cet algorithme multiparamétrique pour décider vite qui doit passer à l’angioscanner, sans retarder le patient à haut risque.","precautions":"L’examen compare les pouls et la pression systolique des deux bras, ausculte le cœur à la recherche d’un souffle diastolique et recherche un déficit neurologique.","principe":"Le score ADD-RS compte ces signes en trois groupes ; l’échocardiographie transthoracique ciblée cherche un voile intimal, un épanchement péricardique ou une insuffisance aortique, et des D-dimères normaux avec un score bas rendent la dissection peu probable.","rang":1,"recherche":"Il recherche le terrain, les caractères de la douleur et les signes d’examen du score, puis les signes échographiques de dissection.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.3, Recommendation Table 44, Figure 30","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Si le scanner manque, l’IRM peut le remplacer ; chez le patient instable qui ne peut pas aller au scanner, l’échocardiographie transœsophagienne pose le diagnostic.","mecanisme":"Le sang entre dans la paroi de l’aorte par la déchirure de l’intima et crée un faux chenal qui peut se rompre ou boucher des branches.","nom":"Angioscanner de l’aorte synchronisé à l’ECG, du cou au bassin","pourquoi_ce_choix":"La ligne directrice en fait l’imagerie de première intention, car il est disponible, précis et décrit toute l’aorte, ce qui distingue le type A, opéré en urgence, du type B.","principe":"Le produit de contraste opacifie les deux chenaux et montre le voile intimal, la porte d’entrée, l’extension et les complications.","rang":2,"recherche":"Il recherche un voile intimal, la porte d’entrée, l’extension, une malperfusion, une dilatation ou une rupture.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.3, Recommendation Table 44","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les complications de la dissection proximale (insuffisance aortique, tamponnade, extension aux artères coronaires) changent le geste chirurgical.","nom":"Échocardiographie transœsophagienne","pourquoi_ce_choix":"Elle se fait au bloc ou au lit pour guider l’intervention et détecter les complications, et elle remplace le scanner chez le patient trop instable pour être transporté.","principe":"La sonde placée dans l’œsophage, au contact de l’aorte, montre en détail la valve aortique, la racine de l’aorte et le péricarde.","rang":3,"recherche":"Elle recherche une insuffisance aortique, un épanchement péricardique et l’atteinte de la racine aortique.","src":[{"id":"R-ESC-AORTE","loc":"Recommendation Table 44","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"dissection-aortique","label":"Dissection aortique","pec":{"mesures_generales":["Le patient est surveillé en soins intensifs, avec une mesure invasive de la pression artérielle.","La douleur se traite par des opiacés intraveineux, ce qui aide aussi à baisser la pression et la fréquence cardiaque."],"moyens_specifiques":[{"dose_ref":null,"limites":"En cas d’ischémie de la moelle épinière ou de malperfusion, une pression moyenne plus haute est recommandée. Le traitement à donner en cas de contre-indication aux bêtabloquants reste À vérifier dans l’algorithme de la ligne directrice.","mecanisme":"Chaque éjection du ventricule gauche pousse le sang dans le faux chenal et étend la déchirure de la paroi aortique.","pourquoi_ce_choix":"La ligne directrice place le bêtabloquant en première ligne, parce qu’il agit à la fois sur la fréquence et sur la pression, et n’ajoute le vasodilatateur qu’ensuite.","principe":"On diminue la force et la fréquence des éjections et la pression contre la paroi : c’est le traitement anti-impulsif.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.1, Recommendation Table 45, Figure 31","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un bêtabloquant intraveineux (labétalol ou esmolol) vise une pression systolique inférieure à 120 mmHg et une fréquence cardiaque d’au plus 60 par minute ; un vasodilatateur intraveineux s’ajoute si la cible de pression n’est pas atteinte. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La mortalité opératoire reste de 17 à 25 % ; un transfert vers un centre aortique à fort volume s’envisage s’il ne retarde pas l’intervention.","mecanisme":"Dans le type A, la dissection atteint l’aorte ascendante et menace de se rompre dans le péricarde ou d’atteindre la valve aortique et les artères coronaires.","pourquoi_ce_choix":"Sans chirurgie, la mortalité atteint environ 50 % dans les 48 premières heures, soit 1 à 2 % par heure.","principe":"On remplace l’aorte ascendante pour fermer la porte d’entrée et supprimer le faux chenal proximal.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.2, Recommendation Table 46","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La dissection de type A impose un avis chirurgical et une intervention immédiats.","type":"chirurgie"},{"dose_ref":null,"limites":"Il exige une anatomie adaptée et un centre expérimenté ; ses complications propres restent À vérifier dans la ligne directrice.","mecanisme":"Dans le type B compliqué, le faux chenal de l’aorte descendante écrase le vrai chenal, prive de sang les viscères ou les membres, ou menace de se rompre.","pourquoi_ce_choix":"La ligne directrice préfère le TEVAR à la chirurgie ouverte quand une intervention est nécessaire et que l’anatomie s’y prête.","principe":"On couvre la porte d’entrée par une endoprothèse posée par voie endovasculaire, ce qui renvoie le flux dans le vrai chenal.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.3, recommandations sur la dissection de type B","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le TEVAR (endoprothèse aortique thoracique) est recommandé dans la dissection de type B compliquée ; le type B non compliqué reçoit le traitement médical, et un TEVAR peut s’envisager chez certains patients entre 14 et 90 jours.","type":"interventionnel"}],"objectif":"Le traitement vise à empêcher la rupture et l’extension de la dissection, et à rétablir la perfusion des organes menacés."},"src":[{"id":"R-ESC-AORTE","loc":"§ 9.3","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique"]},"embolie-pulmonaire":{"bloquant":true,"confirmation":"L’embolie se confirme quand l’angioscanner montre un défaut de remplissage segmentaire ou plus proximal chez un patient de probabilité intermédiaire ou élevée ; chez le patient instable, une dysfonction du ventricule droit à l’échocardiographie suffit pour traiter.","exam":{"lignes":[{"mecanisme":"Le caillot, venu le plus souvent d’une thrombose veineuse profonde, est en partie dégradé dès sa formation et libère des D-dimères dans le sang.","nom":"Probabilité clinique par un score validé, puis D-dimères si elle n’est pas élevée","pourquoi_ce_choix":"Cette étape évite des scanners et une irradiation inutiles ; après 50 ans, un seuil ajusté à l’âge peut servir. Elle ne sert pas si la probabilité est élevée, car un résultat normal n’exclut pas alors l’embolie.","principe":"Un score validé (Wells ou Genève) ou le jugement clinique estime la probabilité ; chez un patient de probabilité faible ou intermédiaire, des D-dimères normaux excluent l’embolie sans imagerie.","rang":1,"recherche":"Il recherche des D-dimères élevés chez un patient dont la probabilité clinique n’est pas élevée.","src":[{"id":"R-ESC-EP","loc":"§ 4.1 et 4.2 ; Recommendations for diagnosis (5.6)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Pendant la grossesse, une échographie veineuse de compression se fait d’abord si des signes de thrombose veineuse sont présents ; une scintigraphie de perfusion ou un angioscanner à faible dose s’envisage ensuite. Une scintigraphie de perfusion normale exclut aussi l’embolie.","mecanisme":"Le caillot bloque une ou plusieurs artères pulmonaires et y laisse un vide dans la colonne de sang opacifiée.","nom":"Angioscanner thoracique des artères pulmonaires","pourquoi_ce_choix":"Un défaut segmentaire ou plus proximal confirme l’embolie chez un patient de probabilité intermédiaire ou élevée, et un angioscanner normal l’exclut chez un patient de probabilité faible ou intermédiaire.","principe":"Le produit de contraste injecté dans une veine opacifie les artères pulmonaires, où le caillot apparaît comme un défaut de remplissage.","rang":2,"recherche":"Il recherche un défaut de remplissage dans les artères pulmonaires.","src":[{"id":"R-ESC-EP","loc":"Recommendations for diagnosis (5.6), CTPA ; § 9.1 grossesse","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une embolie massive surcharge brutalement le ventricule droit, qui se dilate et défaille, ce qui provoque le choc.","nom":"Échocardiographie au lit si le patient est instable","pourquoi_ce_choix":"Chez le patient instable, la ligne directrice admet l’échocardiographie au lit ou l’angioscanner en urgence selon la disponibilité ; une dysfonction du ventricule droit justifie alors le traitement de reperfusion.","principe":"L’échocardiographie au lit montre la dilatation et la dysfonction du ventricule droit sans déplacer le patient.","rang":3,"recherche":"Elle recherche une dilatation et une dysfonction du ventricule droit.","src":[{"id":"R-ESC-EP","loc":"Recommendations for diagnosis (5.6), suspected PE with haemodynamic instability","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"embolie-pulmonaire","label":"Embolie pulmonaire","pec":{"mesures_generales":["L’anticoagulation commence sans attendre la confirmation chez un patient de probabilité clinique élevée ou intermédiaire.","Le risque se classe selon l’état hémodynamique, le score PESI ou sPESI, la fonction du ventricule droit et la troponine.","Un patient en choc peut recevoir de la noradrénaline ou de la dobutamine, et une équipe multidisciplinaire peut organiser la reperfusion."],"moyens_specifiques":[{"dose_ref":null,"limites":"Les anticoagulants oraux directs ne se donnent pas en cas d’insuffisance rénale sévère, de syndrome des antiphospholipides, pendant la grossesse ni pendant l’allaitement ; pendant la grossesse, une héparine de bas poids moléculaire à dose fixe selon le poids les remplace.","mecanisme":"La coagulation continue de produire de la fibrine sur le caillot, qui peut alors s’étendre ou récidiver.","pourquoi_ce_choix":"La ligne directrice préfère l’anticoagulant oral direct à l’antivitamine K quand le patient y est éligible ; elle réserve l’héparine non fractionnée au patient instable, chez qui une reperfusion peut suivre.","principe":"On bloque la formation de nouvelle fibrine par un anticoagulant ; la fibrinolyse naturelle de l’organisme dissout ensuite le caillot existant.","src":[{"id":"R-ESC-EP","loc":"§ 6 ; Recommendations 6.7 et 9.1 ; Key messages, liste « what to do and what not to do »","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient stable reçoit une héparine de bas poids moléculaire ou du fondaparinux plutôt que de l’héparine non fractionnée, puis un anticoagulant oral direct (apixaban, dabigatran, édoxaban ou rivaroxaban) de préférence à un antivitamine K. Le patient instable reçoit de l’héparine non fractionnée intraveineuse avec un bolus adapté au poids. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle augmente le risque hémorragique, et elle n’est pas recommandée en routine dans l’embolie à risque intermédiaire ou faible. Ses contre-indications précises restent À vérifier dans la ligne directrice.","mecanisme":"Dans l’embolie à haut risque, l’obstruction massive des artères pulmonaires fait défaillir le ventricule droit et provoque un choc.","pourquoi_ce_choix":"Elle lève l’obstruction plus vite que l’anticoagulation seule, qui empêche l’extension sans dissoudre le caillot, et elle se donne sans plateau technique.","principe":"On dissout rapidement le caillot par un thrombolytique intraveineux pour diminuer la pression contre laquelle le ventricule droit éjecte.","src":[{"id":"R-ESC-EP","loc":"Recommendations 6.6 ; Key messages","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombolyse systémique est recommandée dans l’embolie pulmonaire à haut risque ; une thrombolyse de sauvetage se fait si l’état se dégrade sous anticoagulation. Le produit et sa posologie restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elles exigent une équipe et un plateau expérimentés sur place ; une assistance circulatoire extracorporelle (ECMO) peut s’y associer en cas de collapsus réfractaire.","mecanisme":"Quand la thrombolyse est contre-indiquée ou échoue, le caillot continue d’obstruer les artères pulmonaires du patient en choc.","pourquoi_ce_choix":"Ces techniques offrent une reperfusion au patient chez qui le risque hémorragique interdit la thrombolyse ou chez qui elle n’a pas suffi.","principe":"On retire le caillot mécaniquement, par une intervention chirurgicale ou par un cathéter introduit jusqu’aux artères pulmonaires.","src":[{"id":"R-ESC-EP","loc":"Recommendations 6.6","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’embolectomie chirurgicale est recommandée, et le traitement percutané par cathéter s’envisage, chez le patient à haut risque dont la thrombolyse est contre-indiquée ou a échoué.","type":"chirurgie"}],"objectif":"Le traitement vise à empêcher l’extension du caillot et la récidive, et, en cas de choc, à lever l’obstruction pour soulager le ventricule droit."},"src":[{"id":"R-ESC-EP","loc":"§ 4 à 6 et 9","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique","urg-choc"]},"etat-de-mal-epileptique":{"bloquant":true,"confirmation":"On parle d’état de mal épileptique quand une crise dure plus de 5 minutes, ou quand au moins deux crises se suivent sur plus de 5 minutes sans retour à l’état neurologique antérieur.","exam":{"lignes":[{"mecanisme":"Une hypoglycémie, un trouble des électrolytes, une intoxication, un sevrage ou un taux trop bas d’antiépileptique peuvent provoquer ou entretenir les crises.","nom":"Glycémie capillaire et bilan sanguin d’urgence","pourquoi_ce_choix":"Ces examens sont rapides et désignent une cause curable, comme l’hypoglycémie ; la ligne directrice les inclut dans le bilan initial.","principe":"La glycémie capillaire et le bilan sanguin (formule sanguine, électrolytes avec magnésium, fonctions du foie et des reins, créatine kinase, glucose, hormones thyroïdiennes, toxiques, taux d’antiépileptiques) cherchent une cause qui se corrige.","rang":1,"recherche":"Ils recherchent une hypoglycémie, un trouble métabolique, une intoxication ou un taux d’antiépileptique trop bas.","src":[{"id":"R-DGN-SE","loc":"Diagnostik, Laboruntersuchungen","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une lésion cérébrale aiguë, comme un AVC, une hémorragie, une tumeur ou une infection, peut être la cause de l’état de mal.","nom":"Scanner cérébral, ou IRM si elle est possible","pourquoi_ce_choix":"La ligne directrice demande d’emblée un scanner, ou si possible une IRM, pour trouver une cause qui demande son propre traitement.","principe":"L’imagerie cérébrale montre ces lésions structurelles.","rang":2,"recherche":"Elle recherche une lésion cérébrale à l’origine des crises.","src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Dans l’état de mal non convulsif, les décharges électriques du cerveau persistent sans mouvements visibles.","nom":"Électroencéphalogramme","pourquoi_ce_choix":"Il est essentiel pour diagnostiquer et suivre l’état de mal non convulsif, et pour reconnaître des crises psychogènes non épileptiques.","principe":"L’électroencéphalogramme enregistre l’activité électrique du cerveau et montre ces décharges.","rang":3,"recherche":"Il recherche des décharges épileptiques persistantes.","src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; EEG","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"etat-de-mal-epileptique","label":"État de mal épileptique","pec":{"mesures_generales":["L’équipe protège le patient, libère les voies aériennes et donne de l’oxygène si la saturation est inférieure à 95 % ; elle reste prête à intuber.","Une voie veineuse stable se pose hors du pli du coude, et le pouls, la pression artérielle et l’ECG se surveillent.","Une hypoglycémie se corrige par du glucose intraveineux ; si un alcoolisme est suspecté, la thiamine se donne avant le glucose.","Une fièvre fait rechercher une infection, avec une ponction lombaire si nécessaire, et peut justifier une antibiothérapie précoce."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle peut déprimer la respiration, ce qui impose d’être prêt à intuber ; la ligne directrice exige une dose suffisante dès la première injection.","mecanisme":"Les décharges épileptiques se prolongent quand les mécanismes d’inhibition des neurones ne suffisent plus à les arrêter.","pourquoi_ce_choix":"Le lorazépam intraveineux et le midazolam intramusculaire ont le meilleur niveau de preuve ; le midazolam intramusculaire est au moins aussi efficace, parce qu’il se donne plus vite et sans voie veineuse.","principe":"On renforce l’inhibition neuronale par une benzodiazépine, qui agit en quelques minutes par voie intramusculaire, intraveineuse ou nasale.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufe 1","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le stade 1 repose sur une benzodiazépine à dose suffisante : lorazépam intraveineux, midazolam intramusculaire ou nasal, ou diazépam, avec une seule répétition possible. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La ligne directrice signale que le lévétiracétam n’est pas autorisé pour cette indication en Europe ; son statut en Suisse et les contre-indications du valproate restent À vérifier.","mecanisme":"Une partie des états de mal résiste aux benzodiazépines, et les crises continuent malgré la première ligne.","pourquoi_ce_choix":"Une étude comparative a montré une efficacité semblable du lévétiracétam, de la fosphénytoïne et du valproate, avec un arrêt du status chez environ 45 à 47 % des patients ; la fosphénytoïne n’est pas autorisée en Suisse.","principe":"On ajoute un antiépileptique intraveineux d’action plus longue, qui agit par un autre mécanisme.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufe 2 ; Empfehlungen 18 und 19","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le stade 2 (état de mal résistant aux benzodiazépines) repose en premier choix sur le lévétiracétam ou le valproate intraveineux ; la phénytoïne et le phénobarbital restent des alternatives. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils exigent l’intubation, la ventilation et une surveillance de l’EEG ; leurs complications propres restent À vérifier dans la ligne directrice.","mecanisme":"L’état de mal réfractaire persiste malgré deux lignes de traitement antiépileptique.","pourquoi_ce_choix":"Ces anesthésiques arrêtent les crises que les antiépileptiques n’ont pas arrêtées ; dans un état de mal focal non convulsif réfractaire, on peut parfois renoncer au coma thérapeutique.","principe":"On supprime l’activité épileptique par un anesthésique intraveineux sous ventilation mécanique, en coma thérapeutique guidé par l’EEG.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufen 3 und 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’état de mal réfractaire et super-réfractaire se traite en soins intensifs par propofol ou midazolam, seuls ou associés, ou par thiopental à dose anesthésique.","type":"interventionnel"}],"objectif":"Le traitement vise à arrêter les crises le plus vite possible et à traiter leur cause."},"src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; Diagnostik ; Therapie","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-crise-prolongee"]},"fracture-rocher":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’imagerie du rocher.","exam":{"lignes":[{"mecanisme":"Un traumatisme crânien peut fracturer le rocher et léser le nerf dans son canal osseux.","nom":"Scanner haute résolution du rocher","pourquoi_ce_choix":"Le choix du scanner plutôt que de l’IRM pour l’os n’est pas encore sourcé par une ligne directrice lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"Le scanner haute résolution montre l’os en détail, donc le trait de fracture et le canal facial.","rang":1,"recherche":"Il recherche le trait de fracture et son rapport avec le canal facial.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf ; c’est le seul examen qui chiffre l’atteinte.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"fracture-rocher","label":"Fracture du rocher","pec":{"mesures_generales":["Un avis ORL est demandé.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source européenne.","mecanisme":"Un fragment osseux peut comprimer le nerf, ou le nerf peut être sectionné.","pourquoi_ce_choix":"Les critères qui la font préférer à l’abstention restent À vérifier dans une source européenne.","principe":"On décomprime ou l’on répare le nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Une intervention chirurgicale sur le canal facial peut être indiquée.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à préserver ou à rétablir la continuité du nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site2-genicule","vii-site4-mastoidien"]},"hyperkaliemie":{"bloquant":true,"confirmation":"L’hyperkaliémie se définit par une kaliémie supérieure à 5,5 millimoles par litre ; elle devient menaçante quand elle est sévère ou qu’elle modifie l’ECG.","exam":{"lignes":[{"mecanisme":"L’excès de potassium autour des cellules modifie leur potentiel de repos et ralentit la conduction dans le cœur.","nom":"Électrocardiogramme","pourquoi_ce_choix":"C’est l’outil diagnostique le plus vite disponible, et un ECG toxique associé à une kaliémie sévère impose le calcium intraveineux.","precautions":"Un ECG normal n’exclut pas une hyperkaliémie sévère, dont le premier signe peut être une arythmie ou un arrêt cardiaque.","principe":"L’électrocardiogramme montre des ondes T amples et pointues, un sous-décalage du segment ST, un QRS élargi, une bradycardie ou une tachycardie ventriculaire.","rang":1,"recherche":"Il recherche les signes électriques de toxicité du potassium.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, ECG features ; Fig. 4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’insuffisance rénale, certains médicaments ou la destruction de cellules font monter le potassium du plasma.","nom":"Kaliémie au lit (gaz du sang), confirmée au laboratoire","pourquoi_ce_choix":"La gravité se classe sur la kaliémie, modérée entre 6,0 et 6,4 millimoles par litre et sévère à partir de 6,5, et ce classement guide le traitement.","precautions":"Une hémolyse du prélèvement ou de mauvaises conditions de conservation peuvent donner une fausse hyperkaliémie.","principe":"Le gaz du sang au lit mesure le potassium en quelques minutes, et le laboratoire le confirme.","rang":2,"recherche":"Il recherche le niveau de la kaliémie.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Definition, Causes, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"hyperkaliemie","label":"Hyperkaliémie","pec":{"mesures_generales":["Le patient est évalué selon l’approche ABCDE et placé sous monitorage cardiaque si l’hyperkaliémie est sévère.","La kaliémie et la glycémie se contrôlent de façon répétée pendant le traitement.","La cause, comme un médicament ou une insuffisance rénale, se recherche et se supprime pour prévenir la récidive."],"moyens_specifiques":[{"dose_ref":null,"limites":"Ils ne font pas baisser le potassium ; une extravasation provoque une nécrose des tissus, ce qui exige une voie veineuse sûre.","mecanisme":"L’excès de potassium rend le myocarde instable et l’expose aux arythmies et à l’arrêt cardiaque.","pourquoi_ce_choix":"Ils agissent en premier pour prévenir les arythmies et l’arrêt cardiaque, même si cette pratique repose sur un faible niveau de preuve.","principe":"Le calcium intraveineux protège les cellules cardiaques contre les arythmies, sans faire baisser la kaliémie.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Les sels de calcium intraveineux (chlorure ou gluconate) se donnent en cas d’hyperkaliémie sévère avec des signes à l’ECG. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle provoque une hypoglycémie chez jusqu’à 28 % des patients, surtout si la glycémie de départ est basse ; le salbutamol peut échouer sous bêtabloquant non sélectif et chez une partie des insuffisants rénaux terminaux.","mecanisme":"Le potassium en excès reste dans le plasma, alors que les cellules peuvent en stocker une grande quantité.","pourquoi_ce_choix":"L’insuline avec du glucose est le traitement le plus efficace et le plus fiable pour faire baisser vite la kaliémie, et son association au salbutamol agit mieux que chacun seul.","principe":"L’insuline, donnée avec du glucose, fait entrer le potassium dans les cellules, et le salbutamol renforce cet effet.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’insuline rapide avec du glucose intraveineux se donne en cas d’hyperkaliémie modérée ou sévère, suivie d’une perfusion de glucose si la glycémie de départ est basse ; le salbutamol peut s’y ajouter. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le cyclosilicate de zirconium sodique agit en une heure environ, trop lentement pour remplacer les mesures d’urgence ; la dialyse exige un accès vasculaire et un centre équipé.","mecanisme":"Tant que le potassium n’est pas éliminé, la kaliémie remonte quand l’effet du transfert dans les cellules s’épuise.","pourquoi_ce_choix":"Ce sont les seuls moyens qui diminuent le stock de potassium, alors que le calcium et l’insuline agissent seulement sur ses effets ou sur sa répartition.","principe":"On retire le potassium de l’organisme par un chélateur intestinal ou par la dialyse.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment ; Fig. 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un chélateur oral du potassium (cyclosilicate de zirconium sodique ou patiromer) retire le potassium, et la dialyse s’envisage en cas d’hyperkaliémie réfractaire. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à protéger le cœur, à faire rentrer le potassium dans les cellules, puis à l’éliminer et à prévenir la récidive."},"src":[{"id":"R-ERC-SPEC","loc":"Hypo-/hyperkalaemia and other electrolyte disorders","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-hyperkaliemie"]},"meningite-bacterienne":{"bloquant":true,"confirmation":"La méningite bactérienne se confirme par un liquide cérébrospinal inflammatoire où l’examen direct, la culture ou la PCR identifie une bactérie ; les hémocultures peuvent l’identifier si la ponction est retardée.","exam":{"lignes":[{"mecanisme":"Les bactéries envahissent l’espace sous-arachnoïdien et y provoquent une inflammation qui modifie le liquide cérébrospinal.","nom":"Ponction lombaire et analyse du liquide cérébrospinal","pourquoi_ce_choix":"Elle seule confirme la méningite bactérienne et identifie le germe, alors que les signes cliniques, comme la raideur de nuque ou le signe de Kernig, ont une précision diagnostique faible.","precautions":"Une imagerie cérébrale précède la ponction seulement en cas de déficit focal (hors paralysie d’un nerf crânien), de crise d’épilepsie récente, de score de Glasgow inférieur à 10 ou d’immunodépression sévère ; si la ponction est retardée, l’antibiotique commence avant.","principe":"La ponction lombaire prélève ce liquide ; sa cellularité, son glucose, ses protéines, son lactate, la coloration de Gram, la culture et la PCR montrent l’inflammation et identifient le germe.","rang":1,"recherche":"Elle recherche une hypercellularité du liquide et le germe à l’examen direct, en culture ou par PCR.","src":[{"id":"R-ESCMID-MEN","loc":"Key Questions 1 à 3 ; Imaging before lumbar puncture","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les bactéries responsables de la méningite passent souvent dans le sang.","nom":"Hémocultures avant la première dose d’antibiotique","pourquoi_ce_choix":"Elles identifient le germe quand la ponction lombaire est retardée ou contre-indiquée ; leur rendement baisse après le début de l’antibiotique, d’où leur prélèvement avant la première dose.","principe":"Les hémocultures cultivent ces bactéries et donnent leur sensibilité aux antibiotiques.","rang":2,"recherche":"Elles recherchent la bactérie et sa sensibilité aux antibiotiques.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 2, Blood cultures, recommandation de grade A","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"meningite-bacterienne","label":"Méningite bactérienne","pec":{"mesures_generales":["L’antibiotique commence au plus tard une heure après l’arrivée, et immédiatement dès la suspicion si la ponction lombaire est retardée.","Les contacts de la même maison et les autres contacts proches d’une méningite à méningocoque reçoivent une antibioprophylaxie par ceftriaxone, ciprofloxacine ou rifampicine."],"moyens_specifiques":[{"dose_ref":null,"limites":"La résistance du pneumocoque varie beaucoup entre les pays européens, et la situation suisse reste À vérifier ; le traitement s’adapte ensuite au germe et à son antibiogramme.","mecanisme":"Le pneumocoque, le méningocoque et, chez certains patients, Listeria se multiplient dans le liquide cérébrospinal, et le retard de traitement aggrave le pronostic.","pourquoi_ce_choix":"Ce schéma couvre les germes habituels de l’adulte selon l’âge et la résistance locale ; sans germe identifié, le schéma empirique se poursuit au moins deux semaines.","principe":"On tue les germes probables par un antibiotique intraveineux qui atteint les méninges, choisi selon l’âge, le terrain et la résistance locale.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 5, Table 4.1 et Table 4.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’adulte reçoit une céphalosporine de troisième génération (ceftriaxone ou céfotaxime) ; l’amoxicilline s’y ajoute après 50 ans ou en cas d’immunodépression pour couvrir Listeria, et la vancomycine ou la rifampicine s’y ajoute si le pneumocoque risque d’être moins sensible. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle s’arrête si la méningite n’est pas bactérienne, ou si le germe n’est ni Haemophilus influenzae ni le pneumocoque ; elle n’est pas recommandée chez le nouveau-né.","mecanisme":"L’inflammation intense de l’espace sous-arachnoïdien contribue aux décès et aux séquelles neurologiques, dont la surdité.","pourquoi_ce_choix":"La ligne directrice la recommande fortement en s’appuyant sur une méta-analyse Cochrane favorable.","principe":"On freine cette inflammation par un corticoïde donné en même temps que la première dose d’antibiotique.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 6, Subquestions 6.1 et 6.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La dexaméthasone se donne à tout adulte et à tout enfant atteint de méningite bactérienne aiguë dans les pays à revenu élevé, avec la première dose d’antibiotique ou au plus tard 4 heures après. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à stériliser le liquide cérébrospinal le plus vite possible et à limiter l’inflammation qui lèse le cerveau."},"src":[{"id":"R-ESCMID-MEN","loc":"Key Questions 1 à 9","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-fievre-meninge"]},"neuroborreliose":{"bloquant":false,"confirmation":"La neuroborréliose est certaine si le liquide cérébrospinal inflammatoire montre une synthèse intrathécale d’anticorps spécifiques ou une PCR ou une culture positive.","exam":{"lignes":[{"mecanisme":"La bactérie Borrelia, transmise par une tique, peut atteindre les racines nerveuses et les nerfs crâniens.","nom":"Sérologie de Borrelia (test immuno-enzymatique puis immunoblot)","pourquoi_ce_choix":"C’est un examen sanguin simple que la ligne directrice sur la paralysie faciale exige ; il se demande en cas de suspicion clinique suffisante.","precautions":"La sérologie peut rester négative au tout début de la maladie.","principe":"L’organisme produit des anticorps contre Borrelia : le test immuno-enzymatique les dépiste, et l’immunoblot les confirme.","rang":1,"recherche":"Elle recherche des anticorps IgM et IgG contre Borrelia dans le sang.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"Objectifs ; § 3.3 ; § 3.10","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire devant une paralysie faciale périphérique.","mecanisme":"L’infection du système nerveux déclenche une réaction inflammatoire dans le liquide cérébrospinal.","nom":"Ponction lombaire avec index d’anticorps spécifiques","pourquoi_ce_choix":"Elle seule rend le diagnostic probable ou certain, ce qui fait choisir l’antibiotique et renoncer aux corticoïdes.","principe":"La ponction montre l’inflammation, et l’index d’anticorps prouve que les anticorps se forment dans le système nerveux lui-même.","rang":2,"recherche":"Elle recherche une inflammation du liquide cérébrospinal, une rupture de la barrière hémato-méningée et une synthèse intrathécale d’anticorps contre Borrelia.","src":[{"id":"R-DGN-NB","loc":"§ 3.2 ; § 3.4 ; § 3.10, critères diagnostiques ; § 5.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"neuroborreliose","label":"Neuroborréliose (maladie de Lyme)","pec":{"mesures_generales":["L’efficacité du traitement se juge sur l’évolution clinique.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les contre-indications de chaque antibiotique restent À vérifier dans l’information professionnelle suisse.","mecanisme":"Une infection bactérienne entretient l’atteinte du nerf.","pourquoi_ce_choix":"La doxycycline orale est aussi efficace que les bêtalactamines intraveineuses, avec la même tolérance ; le choix tient compte des allergies, de la grossesse et du mode d’administration. La limite d’âge de 8 ans pour la doxycycline chez l’enfant est levée.","principe":"Un antibiotique élimine la bactérie.","src":[{"id":"R-DGN-NB","loc":"Statements 4 et 5 ; recommandations 14 et 24 ; durée","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une antibiothérapie par doxycycline, ceftriaxone, céfotaxime ou pénicilline G dure 14 jours dans la forme précoce. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Cette règle ne vaut que si le diagnostic est probable ou certain selon les critères du liquide cérébrospinal.","mecanisme":"La paralysie vient ici d’une infection, et non d’une inflammation idiopathique.","pourquoi_ce_choix":"La ligne directrice ne recommande pas d’ajouter des corticoïdes quand la neuroborréliose est probable ou certaine.","principe":"On traite la cause par l’antibiotique, sans ajouter de traitement contre l’inflammation.","src":[{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Aucun corticoïde n’est ajouté à l’antibiotique.","type":"pharmaco"}],"objectif":"Le traitement vise à éradiquer Borrelia et à obtenir la récupération du nerf, qui est presque toujours bonne."},"src":[{"id":"R-DGN-NB","loc":"§ 3.10 ; § 5","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 ; § 2.6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site4-mastoidien"]},"otite-moyenne-compliquee":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie et l’examen ORL.","exam":{"lignes":[{"mecanisme":"Une infection de l’oreille moyenne peut atteindre le nerf facial qui longe la paroi de la caisse du tympan.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple, immédiate et fait partie de tout examen d’une paralysie faciale périphérique.","principe":"L’otoscopie montre l’inflammation du tympan, un écoulement ou un cholestéatome.","rang":1,"recherche":"Elle recherche une otite moyenne aiguë ou chronique et un cholestéatome.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection peut s’étendre à la mastoïde et toucher l’audition.","nom":"Examen ORL spécialisé","pourquoi_ce_choix":"La ligne directrice le demande devant toute anomalie de l’oreille, de la mastoïde, du tympan ou de l’audition.","principe":"Le spécialiste examine l’oreille moyenne, la mastoïde et le tympan, et il teste l’audition.","rang":2,"recherche":"Il évalue l’oreille moyenne, la mastoïde, le tympan et l’audition.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5, dernier alinéa","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une infection grave peut détruire l’os et découvrir le nerf.","nom":"Imagerie du rocher","pourquoi_ce_choix":"L’IRM est indiquée devant un processus du rocher ; le choix entre scanner et IRM reste À vérifier.","principe":"L’imagerie montre une mastoïdite ou une destruction osseuse.","rang":3,"recherche":"Elle recherche une mastoïdite ou une destruction osseuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"otite-moyenne-compliquee","label":"Otite moyenne compliquée de paralysie faciale","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les contre-indications restent À vérifier dans une source suisse ou européenne.","mecanisme":"L’infection et l’inflammation de l’oreille moyenne compriment le nerf.","pourquoi_ce_choix":"Le choix entre ces moyens reste À vérifier dans une source suisse ou européenne.","principe":"On contrôle l’infection et l’on draine l’oreille moyenne.","statut":"À vérifier","texte":"L’ORL choisit entre antibiothérapie, paracentèse et chirurgie de la mastoïde.","type":"autre"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à contrôler l’infection de l’oreille moyenne et à décomprimer le nerf."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.5","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"pneumothorax-sous-tension":{"bloquant":true,"confirmation":"Le diagnostic est clinique chez le patient instable : un pneumothorax avec hypotension ou arrêt cardiaque se traite comme un pneumothorax sous tension sans attendre l’imagerie.","exam":{"lignes":[{"mecanisme":"L’air pénètre dans la plèvre sans pouvoir en sortir ; la pression monte, refoule le médiastin et écrase le retour veineux vers le cœur.","nom":"Examen clinique au lit : signes de pneumothorax avec retentissement hémodynamique","pourquoi_ce_choix":"La ligne directrice fonde le diagnostic du patient instable sur l’examen clinique ou l’échographie au lit, sans attendre de radiographie, car la décompression ne peut pas attendre.","principe":"L’examen associe une détresse respiratoire, une hypoxie, un murmure vésiculaire aboli d’un côté, un emphysème sous-cutané, une déviation de la trachée et des jugulaires turgescentes à une hypotension.","rang":1,"recherche":"Il recherche l’asymétrie de l’auscultation, la déviation de la trachée, la turgescence des jugulaires et l’hypotension.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’air interposé entre les deux feuillets de la plèvre empêche leur glissement l’un contre l’autre à chaque respiration.","nom":"Échographie pleuropulmonaire au lit","pourquoi_ce_choix":"Elle se fait au lit en quelques minutes, même pendant la réanimation, et la ligne directrice l’admet avec l’examen clinique pour décider de la décompression.","principe":"La sonde posée sur le thorax montre si les feuillets de la plèvre glissent ou non ; l’absence de glissement d’un côté évoque le pneumothorax.","rang":2,"recherche":"Elle recherche les signes échographiques d’un pneumothorax du côté suspect.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"pneumothorax-sous-tension","label":"Pneumothorax sous tension","pec":{"mesures_generales":["Le patient reçoit de l’oxygène et reste sous surveillance continue.","La ventilation en pression positive peut transformer un pneumothorax simple en pneumothorax sous tension : l’équipe y pense chez tout patient ventilé qui se dégrade."],"moyens_specifiques":[{"dose_ref":null,"limites":"Une aiguille trop courte échoue souvent à cause de l’épaisseur de la paroi, et il faut une longueur d’au moins 7 cm ; la canule se coude ou se bouche facilement.","mecanisme":"La pression de l’air piégé dans la plèvre comprime le médiastin et bloque le retour du sang veineux vers le cœur.","pourquoi_ce_choix":"Elle est rapide et à la portée de la plupart des équipes de secours ; ce site a le taux d’échec prévu le plus bas, comparé au 2e espace intercostal sur la ligne médioclaviculaire.","principe":"On ouvre une voie de sortie à l’air en ponctionnant la plèvre avec une aiguille.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Treatment recommendations, Needle decompression","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La décompression à l’aiguille, au 4e ou 5e espace intercostal sur la ligne axillaire antérieure, sert de pont rapide ; une thoracostomie ouverte ou un drain thoracique doit la suivre.","type":"interventionnel"},{"dose_ref":null,"limites":"Elle exige une compétence et un matériel adaptés ; chez le patient conscient, l’analgésie et les complications propres du geste restent À vérifier.","mecanisme":"L’air continue de fuir du poumon vers la plèvre tant que la brèche reste ouverte.","pourquoi_ce_choix":"Elle décomprime plus sûrement que l’aiguille, qui échoue souvent ; la ligne directrice la place en premier quand l’expertise est disponible.","principe":"On ouvre largement la plèvre par une incision de la paroi, puis un drain thoracique évacue l’air de façon durable.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis et Treatment recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thoracostomie ouverte se fait immédiatement en cas d’arrêt cardiaque ou d’hypotension sévère si l’équipe a l’expertise, et un drain thoracique la complète.","type":"chirurgie"}],"objectif":"Le traitement vise à évacuer immédiatement l’air sous pression pour rétablir le retour veineux et l’oxygénation."},"src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique","urg-choc"]},"sca":{"bloquant":true,"confirmation":"L’infarctus se confirme par des symptômes d’ischémie avec une élévation et une variation de la troponine ; un sus-décalage persistant du segment ST pose d’emblée le diagnostic de travail d’infarctus avec sus-décalage du ST (STEMI).","exam":{"lignes":[{"mecanisme":"L’occlusion aiguë d’une artère coronaire prive de sang une partie du myocarde, dont la souffrance modifie l’activité électrique en quelques minutes.","nom":"Électrocardiogramme à 12 dérivations dans les 10 minutes","pourquoi_ce_choix":"Il se fait au premier contact médical et trie à lui seul les patients vers une reperfusion immédiate ; la ligne directrice demande de l’enregistrer et de l’interpréter dans les 10 minutes.","precautions":"Un premier tracé non concluant n’exclut pas le diagnostic : un nouveau tracé se fait si les symptômes persistent ou reviennent, et des dérivations supplémentaires se font si une occlusion postérieure est suspectée.","principe":"L’électrocardiogramme enregistre cette activité électrique ; un sus-décalage persistant du segment ST, ou un équivalent, signale une occlusion coronaire en cours.","rang":1,"recherche":"Il recherche un sus-décalage du segment ST, un équivalent de sus-décalage ou d’autres signes d’ischémie.","src":[{"id":"R-ESC-SCA","loc":"§ 3.2, Recommendation Table 2 ; § 5.1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La nécrose des cellules du myocarde libère dans le sang des protéines de leur appareil contractile, dont la troponine.","nom":"Troponine cardiaque ultrasensible selon l’algorithme 0 h/1 h (ou 0 h/2 h)","pourquoi_ce_choix":"Quand l’ECG ne montre pas de sus-décalage, cet algorithme exclut l’infarctus avec une valeur prédictive négative supérieure à 99 % en une à deux heures ; il ne retarde jamais la reperfusion d’un sus-décalage.","principe":"Le dosage ultrasensible mesure la troponine à l’arrivée puis une heure (ou deux heures) plus tard ; le niveau et sa variation classent le patient en exclusion, observation ou confirmation de l’infarctus.","rang":2,"recherche":"Il recherche une élévation de la troponine et sa variation entre deux dosages.","src":[{"id":"R-ESC-SCA","loc":"§ 3.3.4 et 3.3.4.1, Figure 6","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"sca","label":"Syndrome coronarien aigu","pec":{"mesures_generales":["Le patient reste sous monitorage de l’ECG avec un défibrillateur à portée de main, car une arythmie grave peut survenir à tout moment.","L’oxygène se donne seulement si la saturation est inférieure à 90 % ; il n’est pas recommandé en routine au-dessus de 90 %.","Un opioïde intraveineux peut soulager la douleur, et un anxiolytique léger peut aider un patient très anxieux.","Le service de secours transfère le patient suspect de STEMI directement vers un centre d’angioplastie disponible 24 heures sur 24, sans passer par un hôpital qui n’en a pas."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle exige un centre de cardiologie interventionnelle ; si elle n’est pas possible dans les 120 minutes, la fibrinolyse la précède. Après 12 heures de symptômes, elle reste préférée à la fibrinolyse ; après 48 heures sans symptôme persistant, l’angioplastie de routine d’une artère occluse n’est plus recommandée.","mecanisme":"Un caillot formé sur une plaque d’athérome rompue bouche l’artère coronaire, et chaque minute d’occlusion étend la nécrose.","pourquoi_ce_choix":"À délai égal, elle réduit davantage que la fibrinolyse la mortalité, la récidive d’infarctus et l’AVC, et elle traite en même temps la lésion responsable.","principe":"On rouvre l’artère par un cathéter : un guide franchit le caillot, un ballonnet dilate la lésion et un stent la maintient ouverte.","src":[{"id":"R-ESC-SCA","loc":"§ 5.1 et 5.2.1 ; Recommendation Table 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’intervention coronarienne percutanée primaire (angioplastie primaire) se fait si elle est possible dans les 120 minutes qui suivent le diagnostic à l’ECG. Un NSTE-ACS à très haut risque (choc, douleur réfractaire, arythmie grave, complication mécanique) reçoit une coronarographie immédiate ; une coronarographie dans les 24 heures s’envisage pour un NSTE-ACS à haut risque.","type":"interventionnel"},{"dose_ref":null,"limites":"Elle expose à l’hémorragie, et ses contre-indications précises restent À vérifier dans la ligne directrice. Si le sus-décalage ne diminue pas d’au moins 50 % dans les 60 à 90 minutes, une angioplastie de sauvetage s’impose.","mecanisme":"Le thrombus qui bouche l’artère coronaire contient un réseau de fibrine, et le myocarde d’aval meurt tant qu’il persiste.","pourquoi_ce_choix":"Elle se donne partout et vite, ce qui raccourcit l’ischémie quand le transfert est long ; la stratégie pharmaco-invasive prévoit ensuite une coronarographie dans les 2 à 24 heures.","principe":"On dissout la fibrine du caillot par un fibrinolytique injecté dans une veine, sans attendre un centre de cathétérisme.","src":[{"id":"R-ESC-SCA","loc":"§ 5.2.1 et 5.3 ; Recommendation Table 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La fibrinolyse se donne dans les 12 heures qui suivent le début des symptômes quand l’angioplastie primaire n’est pas possible dans les 120 minutes ; le patient part ensuite vers un centre d’angioplastie sans attendre les signes de reperfusion. Le produit et sa posologie restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils augmentent le risque hémorragique : un inhibiteur de la pompe à protons s’y ajoute si le risque d’hémorragie digestive est élevé, et le fondaparinux n’est pas recommandé lors de l’angioplastie primaire.","mecanisme":"Les plaquettes activées sur la plaque rompue et la cascade de la coagulation entretiennent et étendent le thrombus coronaire.","pourquoi_ce_choix":"La ligne directrice recommande ces trois traitements chez tout patient sans contre-indication ; elle propose le prasugrel chez le patient qui n’a pas encore reçu d’inhibiteur P2Y12 et qui part vers l’angioplastie.","principe":"On bloque l’agrégation des plaquettes par deux antiagrégants et la formation de fibrine par un anticoagulant injectable.","src":[{"id":"R-ESC-SCA","loc":"§ 6 ; Recommendation Table 5","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’aspirine, un inhibiteur du récepteur P2Y12 et un anticoagulant parentéral se donnent dès le diagnostic ; la double antiagrégation plaquettaire dure ensuite 12 mois, sauf risque hémorragique élevé. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à rouvrir au plus vite l’artère coronaire occluse pour limiter la nécrose du myocarde, puis à prévenir une nouvelle thrombose."},"src":[{"id":"R-ESC-SCA","loc":"§ 3 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique"]},"schwannome-vestibulaire":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’IRM ; une confirmation histologique n’est pas toujours nécessaire.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur bénigne de la gaine du nerf vestibulaire grossit lentement dans le méat acoustique interne et l’angle ponto-cérébelleux.","nom":"IRM du méat acoustique interne et de l’angle ponto-cérébelleux, T1 avec gadolinium","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; la même technique sert à la surveillance.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Le gadolinium rehausse la tumeur sur les séquences T1, ce qui montre sa taille et son extension.","recherche":"Elle montre la tumeur, sa taille et son extension dans le méat acoustique interne.","src":[{"id":"R-EANO-VS","loc":"Diagnostic Procedures, Imaging ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"schwannome-vestibulaire","label":"Schwannome vestibulaire","pec":{"mesures_generales":["Le dossier est discuté en réunion de concertation pluridisciplinaire, et une chirurgie se fait dans un centre à grand volume.","L’œil est protégé en cas de lagophtalmie."],"moyens_specifiques":[{"limites":"Elle suppose un suivi régulier ; une croissance ou de nouveaux symptômes imposent un traitement.","mecanisme":"Une petite tumeur bénigne peut rester stable longtemps.","pourquoi_ce_choix":"Elle évite les risques d’un traitement chez un patient peu symptomatique.","principe":"On surveille la croissance et l’audition, et l’on ne traite que si la tumeur progresse.","src":[{"id":"R-EANO-VS","loc":"Therapeutic Strategies, Observation ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La tumeur est surveillée par IRM et audiométrie, chaque année pendant 5 ans.","type":"suivi"},{"limites":"Elle menace le nerf facial et l’audition ; le monitorage du nerf facial améliore le résultat, et l’opération se fait dans un centre à grand volume.","mecanisme":"Une grosse tumeur comprime le tronc cérébral et les nerfs voisins.","pourquoi_ce_choix":"C’est l’option de la grosse tumeur compressive, car la radiochirurgie ne convient qu’aux petits volumes.","principe":"On retire la tumeur, en totalité ou en partie, pour lever la compression.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Surgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une exérèse chirurgicale est faite avec monitorage du nerf facial, suivie au besoin d’une radiothérapie ou d’une radiochirurgie.","type":"chirurgie"},{"limites":"Elle ne convient pas aux grosses tumeurs compressives, et la tumeur reste en place sous surveillance.","mecanisme":"Une petite tumeur ou un reste après chirurgie peut continuer de grossir.","pourquoi_ce_choix":"Elle évite une ouverture du crâne pour une petite tumeur ou une récidive après chirurgie.","principe":"Une irradiation très ciblée vise à arrêter la croissance de la tumeur sans l’enlever.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Radiosurgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une radiochirurgie est proposée.","type":"interventionnel"}],"objectif":"Le traitement vise à contrôler la tumeur en préservant la fonction faciale et l’audition."},"src":[{"id":"R-EANO-VS","loc":"Abstract ; Diagnostic Procedures ; Therapeutic Strategies","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]},"sepsis":{"bloquant":true,"confirmation":"Le sepsis est une dysfonction d’organe menaçant la vie, causée par une réponse dérégulée de l’hôte à une infection ; le choc septique en est une forme, avec une dysfonction circulatoire, cellulaire et métabolique qui augmente le risque de décès.","exam":{"lignes":[{"mecanisme":"L’infection déclenche une réponse dérégulée de l’hôte qui altère la perfusion des tissus, et les cellules mal oxygénées produisent du lactate.","nom":"Lactate sanguin","pourquoi_ce_choix":"La ligne directrice suggère de le mesurer chez tout adulte suspect de sepsis, car son niveau est lié à la mortalité ; elle déconseille le qSOFA comme seul outil de dépistage, car sa sensibilité est faible.","precautions":"Un lactate élevé s’interprète selon le contexte clinique, car d’autres causes que le sepsis l’augmentent.","principe":"Le dosage du lactate dans le sang mesure cette hypoperfusion ; avec le temps de recoloration capillaire, il aide à suivre la réanimation.","rang":1,"recherche":"Il recherche une élévation du lactate, signe d’hypoperfusion des tissus.","src":[{"id":"R-SSC-2021","loc":"Recommendations 2, 3 et 7 ; Screening and early treatment","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les bactéries passent du foyer infectieux dans le sang, ou restent enfermées dans un foyer collecté que l’antibiotique atteint mal.","nom":"Hémocultures et prélèvements du foyer, puis imagerie de la source","pourquoi_ce_choix":"Elles servent à adapter puis à réduire l’antibiothérapie, et à repérer vite un foyer qui exige un contrôle de la source ; elles ne doivent jamais retarder l’antibiotique.","principe":"Les cultures identifient le germe et sa sensibilité ; l’imagerie du foyer recherche une collection ou une obstruction à drainer.","rang":2,"recherche":"Elles recherchent le germe, sa sensibilité et un foyer qui demande un drainage.","src":[{"id":"R-SSC-2021","loc":"Recommendations 12 et 27, Rationale","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"sepsis","label":"Sepsis","pec":{"mesures_generales":["Le sepsis et le choc septique sont des urgences : le traitement et la réanimation commencent immédiatement.","Chez le patient en choc septique sous vasopresseur, la réanimation vise d’abord une pression artérielle moyenne de 65 mmHg.","Le temps de recoloration capillaire aide à guider le remplissage, avec les autres mesures de la perfusion."],"moyens_specifiques":[{"dose_ref":null,"limites":"Un traitement trop large chez un patient non infecté expose aux effets indésirables et aux résistances ; quand le sepsis est seulement possible et qu’il n’y a pas de choc, une évaluation rapide de 3 heures au plus précède la décision.","mecanisme":"La multiplication des bactéries entretient la réponse inflammatoire de l’hôte et la défaillance des organes.","pourquoi_ce_choix":"La ligne directrice émet une recommandation forte, car le risque de décès du choc septique est élevé et fortement lié au délai de l’antibiothérapie.","principe":"On tue les bactéries par une antibiothérapie intraveineuse à large spectre, choisie selon le foyer probable et l’écologie locale, puis adaptée au germe.","src":[{"id":"R-SSC-2021","loc":"Recommendations 12 et 13, Time to antibiotics","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’antibiothérapie se donne immédiatement, idéalement dans l’heure, en cas de choc septique possible ou de sepsis probable. Le choix des molécules et leurs posologies restent À vérifier dans une recommandation suisse et dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le remplissage se guide sur des mesures répétées de la perfusion pour éviter la surcharge ; la ligne directrice déconseille la gélatine.","mecanisme":"La vasodilatation et la fuite capillaire diminuent le volume sanguin efficace et la perfusion des organes.","pourquoi_ce_choix":"La ligne directrice recommande les cristalloïdes en première ligne et suggère les solutés balancés, qu’une méta-analyse en réseau associe à une mortalité plus faible que le sérum physiologique.","principe":"On rétablit le volume circulant par des perfusions intraveineuses de cristalloïdes.","src":[{"id":"R-SSC-2021","loc":"Recommendations 5, 32, 33 et 36","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Les cristalloïdes sont le soluté de première ligne, de préférence des cristalloïdes balancés plutôt que le sérum physiologique ; le volume initial que suggère la ligne directrice pour les 3 premières heures reste À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle peut commencer par une veine périphérique, pour une courte durée, plutôt que d’attendre une voie centrale, et la pression artérielle se mesure de façon invasive dès que possible.","mecanisme":"La vasodilatation du choc septique fait chuter la pression artérielle malgré un remplissage suffisant.","pourquoi_ce_choix":"La ligne directrice la préfère aux autres vasopresseurs (dopamine, vasopressine, adrénaline) par une recommandation forte, et une cible de pression plus haute n’apporte pas de bénéfice.","principe":"On contracte les vaisseaux par un vasopresseur pour remonter la pression de perfusion des organes.","src":[{"id":"R-SSC-2021","loc":"Recommendations 6, 37, 43, 44 et 58","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La noradrénaline est le vasopresseur de première ligne ; une corticothérapie intraveineuse s’ajoute si le besoin de vasopresseur persiste. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le geste dépend du foyer et de l’état du patient ; le délai précis selon le foyer reste À vérifier.","mecanisme":"Un foyer collecté, nécrosé ou un matériel infecté entretient l’infection malgré l’antibiotique.","pourquoi_ce_choix":"La ligne directrice en fait une bonne pratique, car le contrôle de la source est un principe clé du traitement que l’antibiotique seul ne remplace pas.","principe":"On évacue ou on retire le foyer infecté : drainage, débridement ou ablation d’un dispositif infecté.","src":[{"id":"R-SSC-2021","loc":"Recommendation 27, Rationale","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le contrôle de la source se fait dès que c’est médicalement et logistiquement possible, après l’identification rapide d’un foyer qui l’exige.","type":"chirurgie"}],"objectif":"Le traitement vise à restaurer la perfusion des organes et à éliminer l’infection le plus vite possible."},"src":[{"id":"R-SSC-2021","loc":"Introduction ; Recommendations 1 à 58","lu_le":"2026-10-17"},{"id":"R-ERC-SPEC","loc":"Sepsis, définitions","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-choc","urg-fievre-meninge"]},"traumatisme-facial":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’examen des rameaux.","exam":{"lignes":[{"mecanisme":"Une plaie de la joue peut sectionner un ou plusieurs rameaux du nerf après sa sortie du crâne.","nom":"Examen de la plaie et cotation rameau par rameau","pourquoi_ce_choix":"La conduite à tenir n’est pas encore sourcée par une ligne directrice suisse ou européenne lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"On teste chaque territoire du visage pour savoir quel rameau ne répond plus.","rang":1,"recherche":"Il recherche le ou les rameaux atteints et une plaie de la parotide.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf, ce que l’examen clinique seul ne montre pas.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"traumatisme-facial","label":"Plaie ou traumatisme des rameaux du nerf facial","pec":{"mesures_generales":["Un avis ORL ou de chirurgie maxillo-faciale est demandé."],"moyens_specifiques":[{"limites":"Les limites et la récupération attendue restent À vérifier dans une source suisse ou européenne.","mecanisme":"Un rameau sectionné ne transmet plus la commande au muscle.","pourquoi_ce_choix":"Le choix entre suture et greffe, et le délai, restent À vérifier dans une source suisse ou européenne.","principe":"On rétablit la continuité du nerf.","statut":"À vérifier","texte":"Le nerf est suturé ou réparé par une greffe nerveuse.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à rétablir la continuité du nerf et à protéger l’œil."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site5-extracranien"]},"tumeur-cerebrale":{"bloquant":false,"confirmation":"Le diagnostic définitif repose sur l’examen histologique et moléculaire du tissu tumoral.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur qui grandit dans le cerveau donne un déficit progressif selon son siège.","nom":"IRM cérébrale sans et avec gadolinium (T2, FLAIR, T1 3D avant et après injection)","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; il prépare aussi le prélèvement et la chirurgie.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Plusieurs séquences distinguent la tumeur du tissu sain, et le gadolinium montre les zones qui prennent le contraste.","recherche":"Elle détecte la tumeur, la situe et précise sa prise de contraste.","src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"tumeur-cerebrale","label":"Tumeur cérébrale","pec":{"mesures_generales":["Une décision de soins sans diagnostic tissulaire reste exceptionnelle."],"moyens_specifiques":[{"limites":"L’étendue de l’exérèse se limite quand la tumeur touche une zone fonctionnelle ; la suite du traitement dépend du type tumoral et reste hors de ce pilote.","mecanisme":"Le type exact de la tumeur, défini par l’histologie et la biologie moléculaire, décide du traitement.","pourquoi_ce_choix":"Une même intervention donne le diagnostic et traite ; une biopsie seule se réserve aux tumeurs qu’on ne peut pas enlever sans risque.","principe":"On prélève ou l’on enlève la tumeur pour obtenir le tissu et réduire la masse.","src":[{"id":"R-EANO-GLIO","loc":"Tissue acquisition ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une chirurgie première, à visée diagnostique et thérapeutique, est le plus souvent réalisée.","type":"chirurgie"}],"objectif":"Le traitement vise à obtenir un diagnostic tissulaire puis à traiter la tumeur selon son type."},"src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Tissue acquisition","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"tumeur-parotide":{"bloquant":false,"confirmation":"Le diagnostic est confirmé par la cytologie ou l’histologie ; une paralysie faciale avant l’opération est un facteur de mauvais pronostic.","exam":{"lignes":[{"mecanisme":"Une tumeur maligne de la parotide peut envahir le nerf facial, qui traverse la glande.","nom":"Palpation et échographie des parties molles de la face et du cou","pourquoi_ce_choix":"Elle est rapide, disponible chez l’ORL, et elle guide ensuite la cytoponction.","principe":"L’échographie montre la masse dans la glande et les ganglions du cou.","rang":1,"recherche":"Elles recherchent une masse parotidienne et des adénopathies.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung, dernier alinéa","lu_le":"2026-10-17"},{"id":"R-ESMO-SGC","loc":"Diagnostic work-up","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une biopsie au trocart s’impose si la cytoponction ne permet pas de conclure.","mecanisme":"Seule l’étude des cellules distingue une tumeur maligne d’une tumeur bénigne.","nom":"Cytoponction à l’aiguille fine guidée par échographie","pourquoi_ce_choix":"C’est le prélèvement le moins invasif, et une confirmation cytologique ou histologique est obligatoire avant la chirurgie.","principe":"L’aiguille fine aspire des cellules, et le système de Milan classe le risque de malignité.","rang":2,"recherche":"Elle recherche des cellules malignes et classe le risque selon le système de Milan.","src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Un scanner avec injection la remplace si l’IRM est contre-indiquée.","mecanisme":"La tumeur peut s’étendre le long des nerfs et vers les ganglions.","nom":"IRM de la parotide et du cou","pourquoi_ce_choix":"C’est l’imagerie préférée quand une tumeur maligne est suspectée.","principe":"L’IRM montre les tissus mous en détail, dont l’extension le long des nerfs.","rang":3,"recherche":"Elle précise l’extension locale, le long des nerfs et vers les ganglions.","src":[{"id":"R-ESMO-SGC","loc":"Recommendations, imagerie","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"tumeur-parotide","label":"Tumeur maligne de la parotide","pec":{"mesures_generales":["Le patient est informé, avant l’opération, qu’une chirurgie plus étendue peut être nécessaire.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"La résection du nerf laisse une paralysie que seule une reconstruction peut améliorer ; les traitements complémentaires restent À vérifier dans la ligne directrice.","mecanisme":"La tumeur envahit le nerf ; une paralysie avant l’opération signale cette invasion et un moins bon pronostic.","pourquoi_ce_choix":"Une exérèse complète est le traitement de référence, et un nerf déjà paralysé ne garde pas de fonction à préserver.","principe":"On retire toute la glande avec la tumeur, et le nerf envahi avec elle.","src":[{"id":"R-ESMO-SGC","loc":"Surgical management of the primary ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une parotidectomie totale est l’intervention de référence ; une parotidectomie superficielle peut suffire pour une tumeur de bas grade du lobe superficiel ; un nerf facial paralysé avant l’opération est réséqué puis reconstruit.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise une exérèse complète de la tumeur avec une prise en charge du nerf facial."},"src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Surgical management","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 3 Diagnostic différentiel","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site5-extracranien"]},"zona-oticus":{"bloquant":false,"confirmation":"Le diagnostic est clinique devant une paralysie faciale périphérique avec otalgie et vésicules auriculaires ; la sérologie le confirme.","exam":{"lignes":[{"mecanisme":"Le virus varicelle-zona réactivé atteint le nerf et la peau de son territoire sensitif, la conque et le conduit auditif.","nom":"Otoscopie et examen de la conque","pourquoi_ce_choix":"C’est un examen immédiat et sans risque qui change le traitement, car le zona impose un antiviral rapide.","precautions":"Une douleur très intense sans vésicule doit faire évoquer un zona sans éruption.","principe":"L’otoscopie montre les vésicules, même quand elles se limitent au conduit ou au tympan.","rang":1,"recherche":"Elle recherche des vésicules du conduit auditif externe, du tympan ou de la conque.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-CEN-NC9","loc":"Nerf facial (VII), territoire sensitif","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection virale peut atteindre les méninges.","nom":"Sérologie du virus varicelle-zona et ponction lombaire","pourquoi_ce_choix":"La ligne directrice les demande en cas de suspicion clinique ; ils confirment le diagnostic sans retarder l’antiviral.","principe":"La sérologie montre les anticorps contre le virus, et la ponction lombaire une inflammation du liquide cérébrospinal.","rang":2,"recherche":"Elles confirment l’infection par le virus varicelle-zona et recherchent une atteinte méningée.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen ; Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"zona-oticus","label":"Zona otique (syndrome de Ramsay-Hunt)","pec":{"mesures_generales":["L’antiviral débute sans attendre le résultat des examens.","L’œil est protégé et l’audition est surveillée."],"moyens_specifiques":[{"dose_ref":"valaciclovir-po-adulte-zona","limites":"La dose s’adapte à la fonction rénale ; le bénéfice chiffré sur la récupération faciale n’apparaît pas dans les sources lues.","mecanisme":"Le virus varicelle-zona réactivé se multiplie et abîme le nerf ; le pronostic est moins bon que dans la paralysie de Bell.","pourquoi_ce_choix":"La ligne directrice allemande impose un antiviral rapide dans le zona otique, et le protocole des HUG retient le valaciclovir, qui se prend par la bouche.","principe":"Un antiviral freine la multiplication du virus pour limiter l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.1, alinéa sur le zona otique","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné par voie orale, rapidement et systématiquement ; la posologie suit la ligne suisse liée.","type":"pharmaco"},{"dose_ref":"valaciclovir-po-adulte-zona-ir","limites":"Les paliers de clairance suivent l’information professionnelle suisse liée ; une dialyse impose un avis spécialisé, À vérifier.","mecanisme":"Une insuffisance rénale ralentit l’élimination du valaciclovir.","pourquoi_ce_choix":"Le même antiviral reste utilisable, ce qui évite de changer de molécule chez le patient insuffisant rénal.","principe":"On réduit la dose selon la clairance de la créatinine pour éviter l’accumulation.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné à dose adaptée à la clairance de la créatinine, selon la ligne suisse liée.","type":"pharmaco"},{"limites":"La durée et les contre-indications du corticoïde restent À vérifier dans l’information professionnelle suisse.","mecanisme":"L’inflammation du nerf s’ajoute à l’infection virale.","pourquoi_ce_choix":"Le protocole des HUG associe les deux traitements, car chacun agit sur un mécanisme différent.","principe":"Le corticoïde freine l’inflammation pendant que l’antiviral agit sur le virus.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale est associée à l’antiviral. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à limiter l’atteinte du nerf, dont la récupération est moins souvent complète que dans la paralysie de Bell."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.2, 2.5, 2.6, 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3, 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]}};
